import{_ as e,o as a,c as d,a2 as i}from"./chunks/framework.BvlN9b-o.js";const b=JSON.parse('{"title":"为自己的业务接入 Files","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/tutorials/attachments","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"tutorials/attachments.md","filePath":"tutorials/attachments.md"}'),s={name:"tutorials/attachments.md"};function o(r,t,n,c,l,p){return a(),d("div",null,[...t[0]||(t[0]=[i(`<h1 id="为自己的业务接入-files" tabindex="-1">为自己的业务接入 Files <a class="header-anchor" href="#为自己的业务接入-files" aria-label="Permalink to &quot;为自己的业务接入 Files&quot;">​</a></h1><p>目标：为业务资源添加私有附件，复用 Core 文件生命周期和 S3 适配器。前提是 API/PostgreSQL/RustFS 已通过<a href="./../getting-started/quickstart">快速开始</a>运行，资源已有授权策略。业务拥有资源/file 关联表，Files 不知道文档或工单权限。</p><p>完整参考：<a href="./library-grants">授权策略</a>。</p><h2 id="构造与公共接口" tabindex="-1">构造与公共接口 <a class="header-anchor" href="#构造与公共接口" aria-label="Permalink to &quot;构造与公共接口&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/files/mod.rs" target="_blank" rel="noreferrer">Files 类型与服务</a>公开 <code>FileService::from_settings(storage, limits)</code>；替换适配器用 <code>FileService::new(storage, bucket, policy)</code>。<code>UploadInput</code> 为 <code>file_name / content_type / size / sha256</code>；validate 规范化 MIME/摘要并检查预算，start 也重新验证。</p><table tabindex="0"><thead><tr><th>阶段</th><th>公共方法</th><th>返回值</th></tr></thead><tbody><tr><td>注册</td><td><code>start(connection, actor_id, input)</code></td><td><code>Upload</code>，公开 <code>id</code></td></tr><tr><td>重放</td><td><code>load(connection, id)</code></td><td>原 Upload</td></tr><tr><td>签上传</td><td><code>upload_capability(upload)</code></td><td>URL、method、headers、expires_at</td></tr><tr><td>规划完成</td><td><code>plan_completion(connection, id)</code></td><td>Ready / Attempt / Expired / Rejected</td></tr><tr><td>核验</td><td><code>verify_candidate(attempt)</code></td><td>VerifiedCandidate</td></tr><tr><td>放弃</td><td><code>abandon(connection, attempt, rejected)</code></td><td>候选可被清理</td></tr><tr><td>发布</td><td><code>publish(connection, verified)</code></td><td>Adopted / Existing / Expired</td></tr><tr><td>下载</td><td><code>download(connection, id, inline)</code></td><td>DownloadCapability</td></tr></tbody></table><p>这些是方法调用形状；完整签名和类型见源码。<code>CompletionAttempt / VerifiedCandidate</code> 字段私有，必须由服务返回，不能手工制造绕过核验。</p><p>完整参考：<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/knowledge/attachments.rs" target="_blank" rel="noreferrer">Knowledge 附件</a>。</p><h2 id="完整提交边界" tabindex="-1">完整提交边界 <a class="header-anchor" href="#完整提交边界" aria-label="Permalink to &quot;完整提交边界&quot;">​</a></h2><ol><li>短事务 A：验证 Session，锁当前 Membership 和业务资源、授权；claim 幂等命令，start 并写资源/file 关联，complete 只存 upload_id，commit。重放检查关联并 load。事务外签上传，不存短期 URL。</li><li>客户端使用返回 method/headers PUT staging；成功上传仍不在业务附件列表可见。</li><li>短事务 B：再次授权、确认关联，plan_completion 并提交候选记录。Ready 重放仍检查业务已发布关联；Expired/Rejected 明确拒绝。</li><li>事务外 verify_candidate：HEAD、按源 ETag 条件 COPY 到唯一候选、HEAD/完整字节/长度/MIME/SHA-256 校验。候选目标不可覆盖；图片/PDF 另查文件标识。</li><li>短事务 C：重新验证当前凭据、成员、资源/授权/关联和期限，publish、发布业务关联、Audit、commit。失败候选调用 abandon，持久清理记录保留。</li></ol><p>事务外 I/O 后必须重新授权；开始时合法不代表完成时合法。并发完成只采用一个 ready 对象，其他返回相同附件。Audit 失败回滚文件状态和关联，可恢复完成。超时不证明远端写入失败，候选位置先登记再 I/O。</p><h2 id="下载与配置边界" tabindex="-1">下载与配置边界 <a class="header-anchor" href="#下载与配置边界" aria-label="Permalink to &quot;下载与配置边界&quot;">​</a></h2><p>默认单文件 20 MiB、上传 900 秒、下载 60 秒，实际值以<a href="./../reference/config">配置参考</a>为准。下载先检查业务关联和当前资源权限，再对 ready 文件签名；<code>ready_info(connection, ids)</code> 只批量读已授权 IDs，不替业务授权。</p><p>撤权/删除后停止签发新链接，已签 URL 到期前仍可能有效，已接受传输可能继续。业务只保存 file ID，不保存签名 URL。S3 凭据只在 API/Worker，Cookie 不发送到 S3。<code>S3_ENDPOINT</code> 与 <code>S3_PUBLIC_ENDPOINT</code> 分开；按公共 origin 签名，不能事后改 hostname/path。</p><h2 id="验证与恢复" tabindex="-1">验证与恢复 <a class="header-anchor" href="#验证与恢复" aria-label="Permalink to &quot;验证与恢复&quot;">​</a></h2><p>仓库根目录执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bootstrap-storage</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test-storage.mjs</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test-backend.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> attachments</span></span></code></pre></div><p>真实 HTTP/存储测试证明 staging 不可见、唯一发布、大小/类型拒绝、Audit 回滚、关联检查，以及复制期间撤权/Session 过期/资源消失的发布拒绝。过期或 rejected 上传使用新资源；暂时故障重试原资源。自己的业务沿用同样边界，并登记关联迁移、Router、测试与所有权。继续<a href="./document-exports">生成文件与 Jobs</a>和<a href="./deletion-cleanup">对象清理</a>。</p><p>完整参考：<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/apps/api/tests/attachments.rs" target="_blank" rel="noreferrer">真实 HTTP/存储测试</a>。</p><hr><p>源码版本：<code>261be5bb90df</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/docs/tutorials/09-attachments.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,22)])])}const m=e(s,[["render",o]]);export{b as __pageData,m as default};
